import raw from "@/data/catalog.json";
import type { Locale } from "@/i18n/routing";

// Generated by `node catalog/build.mjs` from catalog/tools.json — do not edit src/data/catalog.json by hand.
export type Platform = "windows" | "web";

export interface CatalogCategory {
  id: string;
  en: string;
  ar: string;
  phase: number;
  inputs: string[];
  outputs: string[];
  lateOutputs?: Record<string, number>;
  platforms: Platform[];
}

export interface CatalogTool {
  id: string;
  cat?: string;
  wheel?: string;
  en: string;
  ar: string;
  platforms: Platform[];
  phase: number;
  multi?: boolean;
}

interface CatalogFile {
  stats: { conversions: number; tools: number; actions: number; categories: number };
  categories: CatalogCategory[];
  tools: CatalogTool[];
  actions: CatalogTool[];
}

const catalog = raw as unknown as CatalogFile;

export const stats = catalog.stats;
export const categories = catalog.categories;
export const tools = catalog.tools;

export function toolsOf(categoryId: string): CatalogTool[] {
  return tools.filter((t) => t.cat === categoryId);
}

export function name(item: { en: string; ar: string }, locale: Locale): string {
  return locale === "ar" ? item.ar : item.en;
}
